INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('government-levy-officers-escort', 'government', 10, 'Levy Officers'' Escort', '징발 장교 호위대', 'commander', 'command', 3, 'Senate Guard Hall', '상원 근위청', 1000, 250, 5, NULL, 12, 90, 34, 38, 36, 50, NULL, NULL, NULL, 33, 70, '["roll-call"]', '["government-levy-hatchets","government-aid-post-net-teams"]', 'A short club, a sidearm with a counted clip and a satchel of muster rolls; the runner carries signal flags and one of the few working radios.', '짧은 곤봉과 센 만큼만 받은 탄창이 든 권총, 징집 명부가 든 가죽 가방을 든다. 전령은 신호기와 몇 안 되는 작동하는 무전기를 맡는다.', 'Three layers: a fitted wool coat over a quilted jacket, felt boots in galoshes, and a blue-grey collar stripe with a stamp pouch at the hip.', '세 겹이다. 누빔 솜옷 위에 몸에 맞는 모직 외투를 입고 덧신을 신은 펠트 장화를 신으며, 청회색 깃 줄과 허리에 찬 도장 주머니로 알아본다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('government-senators-sworn-retinue', 'government', 20, 'Senator''s Sworn Retinue', '상원의원 근위 수행대', 'commander', 'champion', 4, 'Senate Guard Hall', '상원 근위청', 1900, 475, 2, NULL, 10, 110, 52, 52, 55, 85, NULL, NULL, NULL, 33, 85, '["thin-clad","last-to-leave"]', '["government-station-guard-shield-line","government-levy-pickmen","government-aid-post-net-teams"]', 'Heavy fighting knives, a plate-backed breast piece under the coat and a sidearm with a counted clip. They are kin and sworn men of the Senator''s house, trained to stand beside a champion in a duel.', '묵직한 전투용 단검과 외투 안의 흉갑판, 센 만큼만 받은 탄창이 든 권총을 갖춘다. 상원의원 집안의 친족과 맹세한 사람들로, 결투하는 투사 곁을 지키도록 훈련받는다.', 'Two layers: a fitted dark coat over a short jacket, a blue-grey sash with the Electorate''s seal pin, and almost no patching.', '두 겹이다. 짧은 웃옷 위에 몸에 맞는 어두운 외투를 입고 청회색 띠와 선구 인장 핀을 달며, 기운 자리가 거의 없다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('government-levy-spears', 'government', 30, 'Levy Spears', '징발 창병', 'infantry', 'line', 1, 'Levy Ledger Office', '징발 장부소', 210, 52, NULL, NULL, 60, 69, 18, 32, 24, 10, NULL, NULL, NULL, 30, 40, '["ledger-levy","charge-breaker"]', '["government-ski-scouts","government-ski-raiders"]', 'Long spears cut from scaffold pipe and a tin helmet each; the squad shares one sack of spare felt-boot liners.', '비계 파이프를 잘라 만든 긴 창과 양철 철모를 하나씩 든다. 분대 전체가 펠트 장화 속감 여벌 한 자루를 나눠 쓴다.', 'Five layers: a greatcoat with a quilted jacket over it, padded trousers, felt boots and an ear-flap cap, with a patched blue-grey levy armband.', '다섯 겹이다. 외투 위에 누빔 솜옷을 겹쳐 입고 솜 덧바지, 펠트 장화, 귀덮개 모자를 쓰며 기운 청회색 징발 완장을 찬다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('government-levy-hatchets', 'government', 40, 'Levy Hatchets', '징발 손도끼병', 'infantry', 'shock', 1, 'Levy Ledger Office', '징발 장부소', 240, 60, NULL, NULL, 50, 66, 28, 20, 32, 5, NULL, NULL, NULL, 34, 38, '["ledger-levy"]', '["government-levy-slingers","government-levy-reserve-rifles"]', 'Hand hatchets and crowbars from the work stores, with shields cut from old door panels. They are sent in at the run to break a firing line.', '작업 창고에서 꺼낸 손도끼와 쇠지렛대를 들고, 낡은 문짝을 잘라 만든 방패를 든다. 사격선을 깨려고 달려 들어가는 분대다.', 'Five layers, with sleeves from one coat and a collar from another, and a blue-grey armband tied above the elbow.', '다섯 겹이다. 소매는 한 외투에서, 깃은 다른 외투에서 떼어 왔고 팔꿈치 위에 청회색 완장을 묶는다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('government-levy-pickmen', 'government', 50, 'Levy Pickmen', '징발 곡괭이병', 'infantry', 'shock', 1, 'Levy Ledger Office', '징발 장부소', 260, 65, NULL, NULL, 40, 70, 24, 22, 38, 8, NULL, NULL, NULL, 32, 40, '["ledger-levy","tunnel-fighter"]', '["government-levy-slingers","government-ledger-marksmen"]', 'Mining picks and short mattocks taken from tunnel work gangs; a rope is tied between every four pickmen so the line holds together in the dark.', '굴 파는 작업반에서 가져온 곡괭이와 짧은 괭이를 든다. 어둠 속에서 대열이 흩어지지 않도록 네 사람마다 밧줄 하나로 서로를 묶는다.', 'Four layers made for the tunnels: quilted jacket, padded trousers, felt boots and a pile-lined cloth cap, with a numbered work tag on the left breast.', '굴길에 맞춘 네 겹이다. 누빔 솜옷, 솜 덧바지, 펠트 장화, 털을 댄 천 모자를 쓰고 왼쪽 가슴에 번호 달린 작업 표를 단다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('government-drill-yard-spears', 'government', 60, 'Drill Yard Spears', '연병장 창병', 'infantry', 'line', 2, 'Ledger Drill Yard', '장부 연병장', 480, 120, NULL, NULL, 50, 72, 24, 38, 28, 25, NULL, NULL, NULL, 31, 52, '["charge-breaker"]', '["government-ski-raiders","government-line-riflemen"]', 'Spears with welded steel heads and lashed cross-bars, drilled to brace together at the yard sergeant''s shout.', '용접한 쇠 창날과 묶은 가로대가 달린 창을 들고, 연병장 하사의 구령에 맞춰 한꺼번에 받치는 훈련을 한다.', 'Four layers: greatcoat, quilted jacket, padded trousers and felt boots, with a washed, whole armband carrying the drill yard number.', '네 겹이다. 외투, 누빔 솜옷, 솜 덧바지, 펠트 장화를 갖추고 연병장 번호가 든, 빨아 둔 멀쩡한 완장을 찬다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('government-station-guard-shield-line', 'government', 70, 'Station Guard Shield Line', '역 경비 방패열', 'infantry', 'line', 2, 'Ledger Drill Yard', '장부 연병장', 560, 140, NULL, NULL, 40, 80, 24, 42, 24, 40, NULL, NULL, NULL, 28, 55, '["shield-line"]', '["government-levy-reserve-rifles","government-levy-slingers"]', 'Riot shields, batons and a pry bar each, kept from the old station patrols; a few carry a sidearm with a counted clip.', '옛 역 순찰대에서 물려받은 진압 방패와 경찰봉, 쇠지렛대를 하나씩 든다. 몇 명은 센 만큼만 받은 탄창이 든 권총을 찬다.', 'Four layers under a dark coat: padded trousers and felt boots in galoshes, a blue-grey collar stripe, and the station number painted on each shield.', '어두운 외투 안에 네 겹을 입는다. 솜 덧바지와 덧신을 신은 펠트 장화를 갖추고 청회색 깃 줄을 달며, 방패마다 역 번호를 칠한다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('government-breach-crews', 'government', 80, 'Breach Crews', '문 따기 조', 'infantry', 'breacher', 3, 'Ledger Drill Yard', '장부 연병장', 900, 225, 6, NULL, 24, 85, 34, 30, 48, 45, NULL, NULL, NULL, 31, 66, '["breach-charge","tunnel-fighter"]', '["government-light-mortar-crews","government-ski-scouts","government-aid-post-net-teams"]', 'Long pry bars, sledgehammers and a hand-pumped rescue spreader, with blasting charges carried in sacks by pairs of crew.', '긴 쇠지렛대와 큰 망치, 손으로 펌프질하는 구조용 벌림기를 쓰고, 폭약은 두 사람이 한 조로 자루에 담아 나른다.', 'Three layers: a fitted quilted coat, padded trousers and felt boots in galoshes, with leather mittens on cords and a blue-grey armband.', '세 겹이다. 몸에 맞는 누빔 외투, 솜 덧바지, 덧신을 신은 펠트 장화를 갖추고 끈에 맨 가죽 장갑과 청회색 완장을 찬다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('government-pipe-charge-hunters', 'government', 90, 'Pipe Charge Hunters', '장대 폭약 사냥조', 'infantry', 'anti-armour', 3, 'Ledger Drill Yard', '장부 연병장', 950, 238, 4, NULL, 20, 80, 32, 26, 60, 35, NULL, NULL, NULL, 32, 64, '["machine-hunter","plate-biter"]', '["government-light-mortar-crews","government-line-riflemen","government-ski-raiders"]', 'Scaffold pipes with a shaped charge lashed to the head, and a hooked cutter for hatches and drone rotors.', '비계 파이프 끝에 성형 폭약을 묶은 장대와, 해치와 드론 날개를 따는 갈고리 절단기를 든다.', 'Three layers: a fitted quilted coat, padded trousers, felt boots and a hood over a cloth cap, with a blue-grey armband.', '세 겹이다. 몸에 맞는 누빔 외투, 솜 덧바지, 펠트 장화를 갖추고 천 모자 위에 두건을 쓰며 청회색 완장을 찬다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('government-senate-guard-shield-line', 'government', 100, 'Senate Guard Shield Line', '상원 근위 방패열', 'infantry', 'line', 4, 'Senate Guard Hall', '상원 근위청', 1500, 375, 3, NULL, 24, 100, 38, 54, 40, 80, NULL, NULL, NULL, 29, 82, '["shield-line","thin-clad","last-to-leave"]', '["government-levy-reserve-rifles","government-ski-raiders","government-aid-post-net-teams"]', 'Tall ballistic shields in matched sets and a heavy blade each. The best rifles in the north hang slung on their backs, with a sidearm and a counted clip.', '짝을 맞춘 키 큰 방탄 방패와 묵직한 칼을 하나씩 든다. 북쪽에서 가장 좋은 소총을 등에 메고, 센 만큼만 받은 탄창이 든 권총을 찬다.', 'Two layers: a fitted dark coat over a short jacket, a blue-grey sash and almost no patching.', '두 겹이다. 짧은 웃옷 위에 몸에 맞는 어두운 외투를 입고 청회색 띠를 두르며, 기운 자리가 거의 없다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('government-levy-slingers', 'government', 110, 'Levy Slingers', '징발 투석병', 'missile', 'skirmish', 1, 'Levy Ledger Office', '징발 장부소', 180, 45, NULL, NULL, 30, 62, 10, 10, 18, 5, 9, 100, 14, 38, 38, '["ledger-levy","muscle-powered"]', '["government-levy-spears","government-drill-yard-spears"]', 'Slings of braided cable and pouches of bolts, nuts and cut steel slugs gathered from the rail yards; no powder and no primers are needed.', '꼰 케이블로 만든 투석끈과 철도 차량기지에서 주워 모은 볼트, 너트, 쇠토막이 든 주머니를 쓴다. 화약도 뇌관도 필요 없다.', 'Five layers with mittens on cords, a quilted jacket, padded trousers, an ear-flap cap and felt boots, and a blue-grey armband.', '다섯 겹이다. 끈에 매단 벙어리장갑, 누빔 솜옷, 솜 덧바지, 귀덮개 모자, 펠트 장화를 갖추고 청회색 완장을 찬다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('government-levy-reserve-rifles', 'government', 120, 'Levy Reserve Rifles', '징발 예비 소총반', 'missile', 'rifle', 1, 'Levy Ledger Office', '징발 장부소', 300, 75, NULL, 'ammo', 30, 66, 14, 14, 22, 8, 18, 145, 8, 33, 38, '["ledger-levy"]', '["government-levy-spears","government-levy-hatchets"]', 'Older rifles out of reserve stores, some missing a magazine. Each levy draws a counted handful of rounds, and an empty rifle still serves as a bayonet staff.', '예비 창고에서 나온 낡은 소총을 들고, 탄창이 없는 총도 있다. 징발병마다 센 만큼의 탄을 받으며, 빈 총은 총검 달린 지팡이로 쓴다.', 'Five layers: greatcoat, quilted jacket, padded trousers, felt boots and an ear-flap cap, with a blue-grey levy armband stitched with the squad number.', '다섯 겹이다. 외투, 누빔 솜옷, 솜 덧바지, 펠트 장화, 귀덮개 모자를 갖추고 분대 번호를 수놓은 청회색 징발 완장을 찬다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('government-line-riflemen', 'government', 130, 'Line Riflemen', '정규 소총반', 'missile', 'rifle', 2, 'Firing School', '사격 교습소', 580, 148, NULL, 'ammo', 32, 68, 16, 17, 24, 18, 24, 150, 16, 33, 52, '["hand-loaded"]', '["government-drill-yard-spears","government-levy-pickmen","government-levy-officers-escort"]', 'Bolt-action rifles of mixed make, each slung on a belt cut from a different coat, and a canvas sack for spent brass that the riflemen refill by hand. The officer counts the rounds out before the line moves.', '제각각인 볼트식 소총을 서로 다른 외투에서 잘라 낸 끈으로 멘다. 쓴 탄피는 천 자루에 모아 손으로 다시 채우고, 장교가 대열을 움직이기 전에 탄을 센 만큼 나눠 준다.', 'Four layers: a long greatcoat over a quilted jacket, puttees over felt boots, a field cap under the hood and a blue-grey collar stripe.', '네 겹이다. 누빔 솜옷 위에 긴 외투를 입고 펠트 장화에 각반을 감으며 두건 안에 야전모를 쓰고 청회색 깃 줄을 단다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('government-ledger-marksmen', 'government', 140, 'Ledger Marksmen', '장부 저격반', 'missile', 'marksman', 3, 'Arms Repair Works', '병기 정비창', 1050, 262, 4, 'ammo', 14, 70, 16, 18, 24, 25, 70, 220, 8, 34, 66, '["skilled-crew","quiet-step"]', '["government-levy-officers-escort","government-senators-sworn-retinue"]', 'Scoped bolt-action rifles kept in oiled cloth. Each marksman is issued eight rounds, counted out and counted back.', '기름 먹인 천에 싸 둔 조준경 달린 볼트식 소총을 쓴다. 저격수마다 여덟 발을 받고, 나갈 때와 돌아올 때 센다.', 'Three layers: a fitted quilted coat, a grey hood and felt boots with galoshes, and a blue-grey collar stripe worn inside the hood.', '세 겹이다. 몸에 맞는 누빔 외투와 잿빛 두건, 덧신을 신은 펠트 장화를 갖추고 청회색 깃 줄은 두건 안쪽에 단다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('government-light-mortar-crews', 'government', 150, 'Light Mortar Crews', '경박격포조', 'missile', 'artillery', 3, 'Arms Repair Works', '병기 정비창', 1050, 262, 5, 'ammo', 12, 68, 14, 14, 20, 15, 160, 380, 12, 32, 70, '["skilled-crew"]', '["government-levy-spears","government-drill-yard-spears","government-levy-hatchets"]', 'Light mortars carried in three pieces, a sledge of shells hauled by hand, and a plotting board scratched on a slate.', '세 조각으로 나눠 나르는 경박격포와, 손으로 끄는 포탄 썰매, 석판에 긁어 그린 사격판을 쓴다.', 'Three layers: heavy quilted coats, leather mittens on cords and felt boots, oil-stained and smelling of the gun works.', '세 겹이다. 두툼한 누빔 외투와 끈에 맨 가죽 장갑, 펠트 장화를 갖추고, 포창 냄새가 배어 기름때가 묻어 있다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('government-heavy-mortar-battery', 'government', 160, 'Heavy Mortar Battery', '중박격포 포대', 'missile', 'artillery', 4, 'State Gun Works', '국가 포창', 1800, 450, 3, 'ammo', 12, 70, 14, 16, 20, 20, 300, 460, 10, 28, 80, '["skilled-crew"]', '["government-station-guard-shield-line","government-senate-guard-shield-line","government-levy-officers-escort"]', 'Heavy mortars on skid bases with shells stacked on sledges. The battery''s rounds are counted at the works before it leaves.', '썰매 받침 위에 놓은 중박격포와 썰매에 쌓은 포탄을 쓴다. 포대는 포창을 떠나기 전에 가져갈 포탄을 센다.', 'Two layers: a quilted coat and a leather apron, with leather mittens on cords, oil-stained and smelling of the gun works.', '두 겹이다. 누빔 외투에 가죽 앞치마를 두르고 끈에 맨 가죽 장갑을 끼며, 포창 냄새가 배어 기름때가 묻어 있다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('government-ski-scouts', 'government', 170, 'Ski Scouts', '스키 정찰대', 'fast', 'recon', 2, 'Ledger Drill Yard', '장부 연병장', 520, 130, NULL, NULL, 12, 90, 22, 20, 24, 10, NULL, NULL, NULL, 66, 52, '["frost-hardened","scout-deploy","quiet-step"]', '["government-levy-slingers","government-levy-reserve-rifles","government-flight-section-scout-drones"]', 'Wooden skis, spiked poles, a short axe each and a signal lamp for the squad; they carry no rifles and no rounds.', '나무 스키와 쇠못 박힌 지팡이, 짧은 도끼를 하나씩 들고 분대마다 신호등 하나를 지닌다. 소총도 탄도 지니지 않는다.', 'Six layers for the surface: a hooded quilted jacket over a greatcoat, padded over-trousers, felt boots and a white sheet over the lot, with a blue-grey band on the pole.', '지상에 맞춘 여섯 겹이다. 외투 위에 두건 달린 누빔 솜옷을 입고 솜 덧바지와 펠트 장화를 갖추며 그 위에 흰 천을 둘러쓰고, 지팡이에 청회색 띠를 감는다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('government-ski-raiders', 'government', 180, 'Ski Raiders', '스키 습격대', 'fast', 'raider', 2, 'Ledger Drill Yard', '장부 연병장', 640, 160, NULL, NULL, 14, 95, 30, 22, 32, 15, NULL, NULL, NULL, 68, 55, '["frost-hardened","quiet-step"]', '["government-levy-reserve-rifles","government-aid-post-net-teams","government-flight-section-scout-drones"]', 'Skis, hand axes and satchels of blasting powder, used to hit supply sleds and a firing line''s flank from the frozen riverbank.', '스키와 손도끼, 폭약 가방을 쓰며, 얼어붙은 강둑에서 보급 썰매와 사격선의 옆구리를 친다.', 'Six layers: a hooded quilted jacket, padded trousers, felt boots and a white sheet over a greatcoat, with a blue-grey armband under the sheet.', '여섯 겹이다. 외투 위에 두건 달린 누빔 솜옷과 솜 덧바지, 펠트 장화를 갖추고 흰 천을 덮으며, 청회색 완장은 천 안쪽에 찬다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('government-flight-section-scout-drones', 'government', 190, 'Flight Section Scout Drones', '비행반 정찰 드론조', 'drone', 'recon', 3, 'State Flight Section', '국가 비행반', 1000, 250, 4, 'cells,parts', 6, 55, 10, 6, 18, 0, NULL, NULL, NULL, 80, 60, '["radio-linked"]', '["government-line-riflemen","government-light-mortar-crews"]', 'Six small rotor airframes with camera lenses, flown on a short radio link. The crew sew spare cells into their vests.', '카메라 렌즈를 단 소형 회전익 기체 여섯 대를 짧은 무선 연결로 날린다. 조종조는 예비 전지를 조끼에 꿰매 넣는다.', 'The crew wear three thin layers under a coat, because cold hands cannot fly, and carry the drones warm inside their coats.', '조종조는 외투 속에 얇은 세 겹을 입는다. 언 손으로는 날릴 수 없기 때문이며, 드론도 외투 안에 품어 데운다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('government-flight-command-strike-wing', 'government', 200, 'Flight Command Strike Wing', '비행 지휘소 타격 편대', 'drone', 'strike', 4, 'State Flight Command', '국가 비행 지휘소', 1800, 450, 2, 'cells,parts', 6, 70, 10, 8, 18, 5, 140, 220, 2, 80, 78, '["fibre-guided","skilled-crew"]', '["government-light-mortar-crews","government-ledger-marksmen","government-armoured-carrier-section"]', 'Six larger airframes each slung with one drop charge and flown on a trailing fibre line that a jammer cannot cut. The crew wind the reel by hand.', '더 큰 기체 여섯 대에 투하 폭약을 하나씩 달고, 전파 방해로 끊을 수 없는 광섬유 줄을 끌며 날린다. 조종조가 릴을 손으로 감는다.', 'The crew wear two thin layers under a coat, a blue-grey sash and a visor against the cold.', '조종조는 외투 속에 얇은 두 겹을 입고 청회색 띠를 두르며, 추위를 막는 챙을 쓴다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('government-armoured-carrier-section', 'government', 210, 'Armoured Carrier Section', '장갑 수송차반', 'war-machine', 'armour', 3, 'Arms Repair Works', '병기 정비창', 1100, 275, 4, 'fuel,parts', 2, 4200, 25, 22, 250, 100, NULL, NULL, NULL, 38, 80, '[]', '["government-station-guard-shield-line","government-levy-reserve-rifles","government-line-riflemen"]', 'Armoured carriers from the old depots with a welded plough blade on the nose, run on rationed fuel. A hand crank frees the hatch locks when the power fails.', '옛 차량기지에서 나온 장갑 수송차에 용접한 제설 날을 앞에 달고 배급 연료로 굴린다. 동력이 끊기면 손 크랭크로 해치 잠금을 푼다.', 'The crew wear three layers: padded leather helmets and short coats that will not snag in a hatch, with a blue-grey stripe painted on the hull.', '조종조는 세 겹을 입는다. 누빔 가죽 헬멧과 해치에 걸리지 않는 짧은 외투를 입고, 차체에는 청회색 줄을 칠한다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('government-field-gun-battery', 'government', 220, 'Field Gun Battery', '야포 포대', 'war-machine', 'artillery', 4, 'State Gun Works', '국가 포창', 1700, 425, 3, 'ammo,fuel', 3, 3600, 10, 8, 250, 40, 330, 420, 12, 24, 100, '["skilled-crew"]', '["government-drill-yard-spears","government-line-riflemen","government-levy-officers-escort"]', 'The few field guns left, towed by a rationed tractor, each with a sledge of shells. Parts are swapped from one barrel to the next to keep them firing.', '남은 몇 문 안 되는 야포를 배급 연료 트랙터로 끌고, 문마다 포탄 썰매를 딸린다. 한 포신에서 다른 포신으로 부품을 옮겨 가며 쏠 수 있게 유지한다.', 'The crew wear two layers: heavy quilted coats and leather mittens on cords, oil-stained and smelling of the gun works.', '포대원은 두 겹을 입는다. 두툼한 누빔 외투와 끈에 맨 가죽 장갑을 갖추고, 포창 냄새가 배어 기름때가 묻어 있다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('government-armoured-gun-carriage', 'government', 230, 'Armoured Gun Carriage', '장갑 포차', 'war-machine', 'armour', 4, 'State Gun Works', '국가 포창', 2000, 500, 2, 'ammo,fuel', 2, 6200, 30, 28, 300, 125, 220, 260, 20, 34, 90, '["iron-dread"]', '["government-station-guard-shield-line","government-levy-slingers"]', 'A tracked carriage with a turret gun and a plough blade, kept alive on parts from two scrapped hulls and run on rationed fuel.', '포탑포와 제설 날을 단 궤도 포차로, 폐차 두 대에서 떼어 낸 부품으로 굴러가고 배급 연료로 움직인다.', 'The crew wear two layers: padded leather helmets and short coats, with the hull plates patched and a blue-grey stripe painted on the turret.', '승무원은 두 겹을 입는다. 누빔 가죽 헬멧과 짧은 외투를 입고, 차체 판은 덧대어 있으며 포탑에는 청회색 줄을 칠한다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('government-revived-depot-tank', 'government', 240, 'Revived Depot Tank', '복원 정비고 전차', 'war-machine', 'armour', 5, 'State Vehicle Depot', '국가 차량고', 3000, 750, 1, 'ammo,fuel', 1, 9000, 40, 40, 360, 140, 440, 300, 16, 30, 100, '["irreplaceable","iron-dread"]', '["government-senate-guard-shield-line","government-heavy-mortar-battery","government-senators-sworn-retinue"]', 'The one heavy tank the state vehicle depot has brought back, with a long main gun and hull plate patched from three other hulls. It moves only with a full tank of fuel and a counted load of shells.', '국가 차량고가 되살린 단 한 대의 중전차로, 긴 주포와 다른 차체 세 대에서 떼어 낸 판을 덧댄 장갑을 지녔다. 연료를 가득 채우고 포탄을 센 만큼 싣고서야 움직인다.', 'The crew wear two layers: padded leather helmets and short coats, and a blue-grey stripe is painted across the hull.', '승무원은 두 겹을 입는다. 누빔 가죽 헬멧과 짧은 외투를 입고, 차체에는 청회색 줄을 가로로 칠한다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('government-aid-post-net-teams', 'government', 250, 'Aid Post Net Teams', '의무소 그물조', 'support', 'countermeasure', 2, 'Ledger Aid Post', '장부 의무소', 500, 125, NULL, NULL, 12, 66, 12, 12, 18, 12, NULL, NULL, NULL, 32, 50, '["net-casting"]', '["government-flight-section-scout-drones","government-flight-command-strike-wing","government-armoured-carrier-section"]', 'Weighted nets on long poles, with rope and stretcher poles drawn from the aid post store. Stretcher teams double as net crews when drones come over the station gate.', '긴 장대에 단 추 달린 그물과, 의무소 창고에서 꺼낸 밧줄과 들것 장대를 쓴다. 드론이 역 문 위로 날아들면 들것조가 그물조를 겸한다.', 'Four layers: a quilted jacket, padded trousers, felt boots and an ear-flap cap, with a blue-grey armband stitched with the aid post number.', '네 겹이다. 누빔 솜옷, 솜 덧바지, 펠트 장화, 귀덮개 모자를 갖추고 의무소 번호를 수놓은 청회색 완장을 찬다.', NULL);
